def application(
    environ: dict[str, Any], start_response: StartResponse
) -> Iterable[bytes]:
    try:
        method = str(environ.get("REQUEST_METHOD", "GET")).upper()
        path = str(environ.get("PATH_INFO", "/"))

        if path == "/":
            # Global cross-reference summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_cross_reference_summary(
                method, environ, start_response
            )

        if path == "/cross-reference-usage":
            # Per-repository cross-reference usage view; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_cross_reference_usage(
                method, environ, start_response
            )

        if path == "/cross-reference-targets":
            # Per-resolved-local-target cross-reference usage view; the
            # handler answers the 405 (Allow: GET) for every other method.
            return _handle_cross_reference_targets(
                method, environ, start_response
            )

        if method == "GET" and path == "/health":
            # Kept byte-for-byte compatible with the documented baseline.
            return _json_response(start_response, "200 OK", {"status": "ok"})

        if path == "/advisories":
            return _handle_advisories(method, environ, start_response)

        if path == "/graph":
            return _handle_graph(method, environ, start_response)

        if path == "/graph/stats":
            return _handle_graph_stats(method, environ, start_response)

        if path == "/dependency-closure-summary":
            # Per-resource dependency closure size summary; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_dependency_closure_summary(
                method, environ, start_response
            )

        if path == "/dependency-usage":
            # Per-depended-upon-resource dependents usage view; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_dependency_usage(method, environ, start_response)

        if path == "/digest-usage":
            # Global resource usage view grouped by registration digest;
            # the handler answers the 405 (Allow: GET) for every other
            # method.
            return _handle_digest_usage(method, environ, start_response)

        if path == "/name-usage":
            # Global resource usage view grouped by registration name;
            # the handler answers the 405 (Allow: GET) for every other
            # method.
            return _handle_name_usage(method, environ, start_response)

        if path == "/graph/path/all":
            return _handle_graph_path_all(method, environ, start_response)

        if path == "/graph/path":
            return _handle_graph_path(method, environ, start_response)

        if path == "/promotion/blockers":
            return _handle_promotion_blockers(method, environ, start_response)

        if path == "/lifecycle":
            # Global lifecycle summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_lifecycle_summary(method, environ, start_response)

        if path == "/dependency-vulnerability-impact":
            # Global dependency vulnerability impact summary; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_global_dependency_vulnerability_impact(
                method, environ, start_response
            )

        if path == "/upload-sessions":
            # Global chunk upload session summary; the handler answers the
            # 405 (Allow: GET) for every other method.
            return _handle_upload_sessions(method, environ, start_response)

        if path == "/content-status":
            # Global finished-content readiness summary; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_content_status(method, environ, start_response)

        if path == "/content-integrity":
            # Global assembled-content digest consistency inspection; the
            # handler answers the 405 (Allow: GET) for every other method.
            return _handle_content_integrity(method, environ, start_response)

        if path == "/vulnerability-exceptions":
            # Global exemption summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_global_vulnerability_exceptions(
                method, environ, start_response
            )

        if path == "/sboms":
            # Global SBOM summary; the handler answers the 405 (Allow: GET)
            # for every other method.
            return _handle_sboms_summary(method, environ, start_response)

